const input  = $input.first().json;
const plan   = input.final_plan || input;
const params = plan.parameters  || {};
const data   = { ...params, ...plan };
const action = (plan.action || '').toLowerCase();

const clean = (v) => (!v || v === 'undefined' || v === 'null') ? '' : String(v).trim();

// Core fields
const user_email   = clean(input.user_email)    || clean(plan.user_email);
const user_name    = clean(input.user_name)     || clean(plan.user_name);
const leave_type   = data.leave_type    || '';
const start_date   = data.start_date    || '';
const end_date     = data.end_date      || '';
const total_days   = data.total_days    || 0;
const reason       = data.reason        || '';
const leave_id     = data.leave_id      || null;
const attendance_id = data.attendance_id || null;
const hours        = data.hours         || 0;
const work_date    = data.work_date     || '';
const employee_id  = input.employee_id  || null;

// Auth fields
const email        = clean(data.email)        || clean(input.user_email);
const password     = clean(data.password)     || '';
const role         = clean(data.role)         || 'staff';
const is_active    = data.is_active !== undefined ? data.is_active : true;
const target_email = clean(data.target_email) || '';
const new_email    = clean(data.new_email)    || '';
const name         = clean(data.name)         || clean(data.user_name) || '';
const employment_start_date = clean(data.employment_start_date) || '';

// Timetable fields
const month_start        = clean(data.month_start)  || clean(input.month_start) || '';
const month_end          = clean(data.month_end)    || clean(input.month_end)   || '';
const shift_id           = data.shift_id            || input.shift_id           || null;
const shift_name         = clean(data.shift_name)   || '';
const start_time         = clean(data.start_time)   || '';
const end_time           = clean(data.end_time)     || '';
const target_employee_id = data.target_employee_id  || input.target_employee_id || null;
const weekdays_only      = data.weekdays_only        || false;
const is_off             = data.is_off               || false;

return [{
  json: {
    action,
    user_email, user_name,
    leave_type, start_date, end_date, total_days, reason,
    leave_id, attendance_id, hours, work_date, employee_id,
    email, password, role, is_active, target_email, new_email, name, employment_start_date,
    month_start, month_end, shift_id, shift_name, start_time, end_time,
    target_employee_id, weekdays_only, is_off,
  }
}];

const row = $input.first()?.json || {};
if (!row?.attendance_id) return [{ json: { success: false, message: 'Punch In failed — no record returned', data: null } }];
return [{ json: { success: true, message: 'Punched In successfully', data: row } }];

const row = $input.first()?.json || {};
if (!row?.attendance_id) return [{ json: { success: false, message: 'Punch Out failed — record not found or already clocked out', data: null } }];
return [{ json: { success: true, message: 'Punched Out successfully', data: row } }];

const row = $input.first()?.json || {};
if (!row?.leave_type_id) {
  const lt = $('Parse Input').first()?.json?.leave_type || 'unknown';
  return [{ json: { success: false, message: `Leave type not found: ${lt}`, data: null } }];
}
const p = $('Parse Input').first().json;
return [{ json: { employee_id: row.employee_id, leave_type_id: row.leave_type_id, status_id: row.status_id, start_date: p.start_date, end_date: p.end_date, total_days: p.total_days, reason: p.reason } }];

const row = $input.first()?.json || {};
if (!row?.leave_id) return [{ json: { success: false, message: 'Leave insert returned no record', data: null } }];
return [{ json: { success: true, message: `Leave application submitted (ID: ${row.leave_id})`, data: row } }];

const row = $input.first()?.json || {};
if (!row?.leave_id) return [{ json: { success: false, message: 'Cancel failed — record not found or already processed', data: null } }];
return [{ json: { success: true, message: 'Leave application cancelled', data: row } }];

const rows = $input.all().map(i => i.json).filter(r => r && r.leave_type_name);
const empDate = rows[0]?.employment_start_date || null;
const bal = { annual_leave_used: 0, sick_leave_used: 0, employment_start_date: empDate };
rows.forEach(r => {
  if (r.leave_type_name === 'Annual Leave') bal.annual_leave_used = Number(r.used) || 0;
  if (r.leave_type_name === 'Sick Leave')   bal.sick_leave_used   = Number(r.used) || 0;
});
return [{ json: { success: true, data: bal } }];

const row = $input.first()?.json || {};
if (!row?.employee_id) {
  const em = $('Parse Input').first()?.json?.user_email || 'unknown';
  return [{ json: { success: false, message: `Employee not found for email: ${em}`, data: null } }];
}
const p = $('Parse Input').first().json;
return [{ json: { employee_id: row.employee_id, status_id: row.status_id, work_date: p.work_date, hours: p.hours, reason: p.reason } }];

const row = $input.first()?.json || {};
if (!row?.overtime_id) return [{ json: { success: false, message: 'Overtime insert returned no record', data: null } }];
return [{ json: { success: true, message: `OT request submitted (ID: ${row.overtime_id}) — ${row.work_date} ${row.hours}h`, data: row } }];

const row = $input.first().json;
if (!row?.email) return [{ json: { success: false, message: 'Invalid email or password.' } }];
return [{ json: { success: true, user: { user_id: row.employee_id, email: row.email, name: row.name || row.email, role: row.role || 'staff', employee_id: row.employee_id, employment_start_date: row.employment_start_date || null } } }];

const row = $input.first()?.json || {};
if (!row?.user_id && !row?.employee_id) return [{ json: { success: false, message: 'Email already exists or insert failed.' } }];
return [{ json: { success: true, message: `User created: ${row.email}`, user: row } }];

const row = $input.first()?.json || {};
if (!row?.user_id && !row?.employee_id) return [{ json: { success: false, message: 'User not found or update failed.' } }];
return [{ json: { success: true, message: `User updated: ${row.email}`, user: row } }];

const row=($input.all()||[])[0]?.json||{};
if(!row?.employee_id&&!row?.email)return[{json:{success:false,message:'User not found or protected account.'}}];
return[{json:{success:true,message:`Account deleted: ${row.email}`,data:row}}];

const row=($input.all()||[])[0]?.json||{};
if(!row?.shift_id)return[{json:{success:false,message:'Create shift failed'}}];
return[{json:{success:true,message:`Shift created: ${row.shift_name}`,data:row}}];

const rows = ($input.all()||[]).map(i=>i?.json).filter(r=>r&&r.timetable_id);
if(!rows.length)return[{json:{success:false,message:'Assignment failed — check date range or employee ID'}}];
return[{json:{success:true,message:`Assigned ${rows.length} day(s)`,data:rows}}];
